import * as React from "react";
import { View, Text, StyleSheet } from "react-native";

export function Tag({ label }) {
  return (
    <View style={styles.tagContainer}>
      <Text style={styles.tagText}>{label}</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  tagContainer: {
    borderRadius: 16,
    borderWidth: 1,
    borderColor: "#293349",
    paddingHorizontal: 8,
    paddingVertical: 4,
  },
  tagText: {
    color: "#293349",
    fontSize: 12,
    fontWeight: "400",
  },
});
